  function buildWinterQueueEvent(station2, cars, canSkip, alternative) {
    const minutes = cars * QUEUE_MINUTES_PER_CAR;
    const choices = [
      choice(
        "winter_queue_wait",
        "Warten",
        `+${minutes} Min bis zur Einfahrt`,
        `Nach ${minutes} Minuten seid ihr dran.`,
        { timeDeltaMin: minutes, stressDelta: 3 }
      )
    ];
    if (canSkip) {
      choices.push(choice(
        "winter_queue_skip",
        "Weiterfahren",
        "Ladestopp auslassen",
        "Ihr fahrt ohne diesen Ladestopp weiter."
      ));
    }
    if (alternative) {
      choices.push(choice(
        "winter_queue_alternative",
        "Langsameren Lader nehmen",
        `${alternative.name} \xB7 ${alternative.maxKw} kW`,
        `Ihr fahrt stattdessen zu \u201E${alternative.name}\u201C.`
      ));
    }
    return {
      id: "evt_winter_charger_queue",
      title: `Warteschlange \xB7 ${station2.name}`,
      icon: "\u{1F50C}",
      category: "charger",
      description: `${cars} Autos warten vor euch. ${canSkip ? "Laut Prognose ist das n\xE4chste Ziel erreichbar." : "F\xFCr die Weiterfahrt ohne Ladestopp reicht die Akku-Reserve laut Prognose nicht."}`,
      choices
    };
  }

