  // src/sim/AlpineDriving.ts
  var ALPINE_PASS_PRESET = "alpine_pass";
  var CHAIN_FITTING_MINUTES = 10;
  var CHAIN_CHECK_CHANCE = 0.35;
  var CHAIN_CHECK_FINE_EUR = 150;
  var CHAIN_CHECK_MINUTES = 8;
  var CHAIN_CHECK_STRESS = 12;
  var PASS_GRIP = {
    snow: { fitted: 1, bare: 0.64 },
    ice: { fitted: 0.78, bare: 0.34 }
  };
  var PASSES = {
    edge_garmisch_innsbruck: { name: "Zirler Berg", climb: 0.55, descent: [0.73, 0.93] },
    edge_muenchen_achenpass_innsbruck: { name: "Achenpass", climb: 0.45, descent: [0.58, 0.7] }
  };
  var ALPINE_DESCENT_MIN_LOSS_M = 800;
  function alpineLeg(levelId, edge, spec) {
    if (levelId !== WINTER_LEVEL_ID) return;
    const pass = spec.reverse ? void 0 : PASSES[edge.id];
    const lossM = spec.reverse ? edge.elevationGainM : edge.elevationLossM;
    const [start, end] = pass?.descent ?? [0.55, 0.85];
    const descent = lossM < ALPINE_DESCENT_MIN_LOSS_M ? void 0 : {
      startKm: start * edge.distanceKm,
      endKm: end * edge.distanceKm,
      lossM
    };
    return {
      pass: pass && { name: pass.name, entryKm: pass.climb * edge.distanceKm },
      descent
    };
  }
  function chainCheckOccurs(chainsFitted, roll) {
    return !chainsFitted && roll < CHAIN_CHECK_CHANCE;
  }
  function passGrip(onIce, chainsFitted) {
    return PASS_GRIP[onIce ? "ice" : "snow"][chainsFitted ? "fitted" : "bare"];
  }
  function passTravelHeading(previous, heading, grip, dt) {
    const arc = heading - previous;
    const shortestArc = Math.atan2(Math.sin(arc), Math.cos(arc));
    return previous + shortestArc * (1 - Math.exp(-18 * grip ** 2 * dt));
  }

  // src/sim/AlpineDescent.ts
  var REGEN_MODES = {
    coast: { label: "Segeln", factor: 0.12 },
    normal: { label: "Normal", factor: 0.6 },
    strong: { label: "B-Modus", factor: 0.9 }
  };
  var REGEN_TAPER_START_PCT = 85;
  var BRAKE_HEAT_LIMIT_M = 550;
  var BRAKE_COOLDOWN_MINUTES = 12;
  var BRAKE_OVERHEAT_STRESS = 14;
  var MAX_REGEN_STEP_KM = 0.1;
  function downhillBraking(lossM, socPct, batteryKwh, mode) {
    const headroomPct = Math.max(0, 100 - socPct);
    const taper = Math.min(1, headroomPct / (100 - REGEN_TAPER_START_PCT));
    const capture = REGEN_MODES[mode].factor * taper;
    const recoveredKwh = Math.min(lossM * CLIMB_ENERGY_KWH_PER_M * capture, batteryKwh * headroomPct / 100);
    return { recoveredKwh, brakeHeatM: lossM - recoveredKwh / CLIMB_ENERGY_KWH_PER_M };
  }
  function brakesOverheat(accumulatedHeatM) {
    return accumulatedHeatM >= BRAKE_HEAT_LIMIT_M;
  }
  function alpineRoadEnergy(profile, fromKm, toKm, baseKwh, socPct, batteryKwh, mode) {
    const result = { netKwh: baseKwh, recoveredKwh: 0, brakeHeatM: 0 };
    if (!profile || toKm <= fromKm) return result;
    const start = Math.max(fromKm, profile.startKm);
    const end = Math.min(toKm, profile.endKm);
    if (end <= start) return result;
    const baseKwhPerKm = baseKwh / (toKm - fromKm);
    const lossMPerKm = profile.lossM / (profile.endKm - profile.startKm);
    let soc = socPct - (start - fromKm) * baseKwhPerKm / batteryKwh * 100;
    const steps = Math.ceil((end - start) / MAX_REGEN_STEP_KM);
    const km = (end - start) / steps;
    for (let step = 0; step < steps && soc > 0.15; step++) {
      const braking = downhillBraking(km * lossMPerKm, soc, batteryKwh, mode);
      soc -= (km * baseKwhPerKm - braking.recoveredKwh) / batteryKwh * 100;
      result.recoveredKwh += braking.recoveredKwh;
      result.brakeHeatM += braking.brakeHeatM;
    }
    result.netKwh -= result.recoveredKwh;
    return result;
  }
  function alpineForecastBoundaries(profile, fromKm, toKm) {
    if (!profile) return [toKm];
    return [profile.startKm, profile.endKm].filter((km) => km > fromKm && km < toKm).concat(toKm);
  }

