  var exitZone = ({ x, y }) => ({ x: x - 43, y: y - 41, w: 86, h: 82 });
  function aachenCityDrive(preset, levelOrder, routeId) {
    const passThrough = preset === "aachen_start";
    const exit = passThrough && levelOrder === 2 ? "brand" : "europaplatz";
    const viaBrand = exit === "brand";
    const motorway3 = viaBrand ? "A44" : "A544";
    const junction = viaBrand ? "Aachen-Brand" : "Europaplatz";
    const signLabel = !viaBrand && routeId === "l1_route_b_nord" ? "A544 \xB7 Kreuz Aachen \u2192 A44 D\xFCsseldorf" : AACHEN_EXITS[exit].label;
    const goal = passThrough ? AACHEN_EXITS[exit] : AACHEN_HOME_POINT;
    return {
      layout: AACHEN,
      exit,
      exitPoint: AACHEN_EXITS[exit],
      goal,
      passThrough,
      signLabel,
      motorway: motorway3,
      junction,
      spawn: passThrough ? { ...AACHEN_HOME_POINT, rot: Math.atan2(17, 103) } : AACHEN_INBOUND,
      target: passThrough ? exitZone(goal) : AACHEN_HOME,
      navLabel: passThrough ? `Zur ${motorway3} \xB7 ${junction}` : "Nach Hause \xB7 Pontviertel",
      completionLabel: `${motorway3} erreicht \xB7 Gute Fahrt!`,
      title: passThrough ? `Aachen \xB7 Zuhause \u2192 ${motorway3} ${junction}` : "Aachen \xB7 Europaplatz \u2192 Zuhause",
      wrongExits: Object.entries(AACHEN_EXITS).filter(([id]) => id !== exit).map(([, sign]) => ({ ...sign, zone: exitZone(sign) }))
    };
  }

